import {
  fetchLighthouseReport,
  isLighthouseReport,
  type LighthouseReport,
} from '@blen/react-lighthouse-viewer';

export type SampleSummary = {
  slug: string;
  thumbnail: string | null;
  url: string;
  lighthouseVersion: string;
  fetchTime: string;
  scores: { id: string; title: string; score: number | null }[];
};

export const reportsUrl = `${import.meta.env.BASE_URL}reports/`;

// The sample reports are generated by `pnpm reports` (and on every Pages deploy), so they are
// always fresh runs of the bundled Lighthouse version. The dev server answers a missing file with
// its HTML page, so a failed request or a parse error both mean "no samples".
export async function loadIndex(): Promise<SampleSummary[]> {
  try {
    const response = await fetch(`${reportsUrl}index.json`);
    return response.ok ? await response.json() : [];
  } catch {
    return [];
  }
}

export type ReportView = { key: string; name: string; report: Promise<LighthouseReport> };

const sampleViews = new Map<string, ReportView>();

// Cached, so each sample keeps one promise and one view object across renders. These promises
// reject with a readable message, which the error boundary around the viewer shows.
export function sampleView(slug: string): ReportView {
  let view = sampleViews.get(slug);
  if (!view) {
    const report = fetchLighthouseReport(`${reportsUrl}${encodeURIComponent(slug)}.json`).catch(
      () => {
        throw new Error(`There is no sample report named ${slug}.`);
      },
    );
    view = { key: slug, name: `${slug} sample report`, report };
    sampleViews.set(slug, view);
  }
  return view;
}

let emptyView: ReportView | undefined;

export function noSamplesView(): ReportView {
  emptyView ??= {
    key: 'no-samples',
    name: 'Report',
    report: Promise.reject(
      new Error('There are no sample reports yet. Open your own report to view it.'),
    ),
  };
  return emptyView;
}

export function hostOf(url: string) {
  return new URL(url).hostname.replace(/^www\./, '');
}

export async function loadFile(file: File): Promise<LighthouseReport> {
  let json: unknown;
  try {
    json = JSON.parse(await file.text());
  } catch {
    throw new Error(`${file.name} is not valid JSON.`);
  }
  return checkReport(file.name, json);
}

function checkReport(name: string, json: unknown): LighthouseReport {
  if (!isLighthouseReport(json)) throw new Error(`${name} is not a Lighthouse JSON report.`);
  return json;
}
